"""Product analytics dashboard: conversion statistics over customer sessions."""


def parse_session_log(lines):
    """Parse log lines into sessions. See SPEC.md section 4."""
    out = []
    flags = {"1": True, "0": False, "": None}
    for number, line in enumerate(lines, start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        fields = line.split(",")
        if len(fields) != 3:
            raise ValueError(f"line {number}: expected three fields")
        id_, day, flag = (field.strip() for field in fields)
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {number}: expected an integer day") from exc
        if flag not in flags:
            raise ValueError(f"line {number}: invalid converted field")
        out.append({"id": id_, "day": day, "converted": flags[flag]})
    return out


def dedupe_sessions(events):
    """Remove duplicate sessions. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Daily counts of converted sessions. See SPEC.md section 6."""
    counts = [0] * (end_day - start_day + 1)
    for e in events:
        if start_day <= e["day"] <= end_day and e["converted"] is True:
            counts[e["day"] - start_day] += 1
    return counts
"""Product analytics dashboard: conversion statistics over customer sessions."""


def conversion_rate(events):
    """The conversion rate of a list of sessions. See SPEC.md section 1."""
    hits = sum(1 for e in events if e["converted"] is True)
    return hits / len(events) if events else 0.0


def pooled_conversion_rate(groups):
    """The pooled conversion rate across groups of sessions. See SPEC.md section 2."""
    total = sum(len(events) for events in groups.values())
    hits = sum(1 for events in groups.values() for e in events if e["converted"] is True)
    return hits / total if total else 0.0


def conversions_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    return sum(daily_counts[-days:]) if days > 0 else 0


def conversion_rate_by_group(groups):
    """The conversion rate of each group. See SPEC.md section 9."""
    return {
        name: conversion_rate(events) if events else None
        for name, events in sorted(groups.items())
    }


def longest_conversion_streak(daily_counts):
    """Longest run of days with converted sessions. See SPEC.md section 10."""
    best = cur = 0
    for c in daily_counts:
        if c > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best
"""Product analytics dashboard: conversion statistics over customer sessions."""
from sales_dashboard.loader import daily_conversion_counts
from sales_dashboard.metrics import pooled_conversion_rate, conversion_rate, conversions_in_window


def campaign_summary(groups, days):
    """Summary of groups of sessions. See SPEC.md section 7."""
    all_events = [e for evts in groups.values() for e in evts]
    if all_events:
        first = min(e["day"] for e in all_events)
        last = max(e["day"] for e in all_events)
        recent = conversions_in_window(daily_conversion_counts(all_events, first, last), days)
    else:
        recent = 0
    return {
        "rate": round(pooled_conversion_rate(groups), 3),
        "recent": recent,
        "groups": sum(1 for events in groups.values() if events),
    }


def top_converting_groups(groups, n):
    """The groups with the highest conversion rate. See SPEC.md section 8."""
    nonempty = (name for name, events in groups.items() if events)
    ranked = sorted(nonempty, key=lambda name: (-conversion_rate(groups[name]), name))
    return ranked[:n]

